import {
  CatchBoundary,
  createFileRoute,
  useRouter,
} from "@tanstack/react-router";
import Post from "./-components/Post";
import { getPost, getPostComments } from "../data/posts";

export const Route = createFileRoute("/posts/$postId")({
  component: RouteComponent,
  onError: (error) => {
    console.error("Error loading post:", error);
  },
  onCatch: (error) => {
    console.error("onCatch", error);
  },
  notFoundComponent: () => <div>Post Not Found</div>,
  errorComponent: ({ error, reset }) => {
    const router = useRouter();
    return (
      <div>
        {error.message} <br />
        <button
          onClick={() => {
            router.invalidate();
          }}
        >
          Retry
        </button>
      </div>
    );
  },
  pendingComponent: () => <div>Loading...</div>,
  pendingMs: 0,
  pendingMinMs: 500,
  loader: async ({ params }) => {
    await new Promise((r) => setTimeout(r, 3000));
    const commentsPromise = getPostComments(+params.postId);
    const post = await getPost(+params.postId);

    return {
      post,
      commentsPromise,
    };
  },
});

function RouteComponent() {
  return <Post />;
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { getPosts } from "../data/posts";
import z from "zod";
import { zodValidator } from "@tanstack/zod-adapter";

const postsSearchParamsSchema = z.object({
  page: z.number().optional(),
});

export const Route = createFileRoute("/posts/")({
  component: RouteComponent,
  validateSearch: zodValidator(postsSearchParamsSchema),
  beforeLoad: () => {
    return {
      getPosts: getPosts,
    };
  },
  loaderDeps: ({ search }) => ({ page: search.page }),
  loader: async ({ context, deps }) => {
    const { getPosts } = context;
    const posts = await getPosts(deps.page);
    return {
      posts: posts.posts,
    };
  },
});

function RouteComponent() {
  const { posts } = Route.useLoaderData();
  return (
    <div>
      Hello "/posts/"! <br />
      {posts.map((post) => (
        <div key={post.id}>
          <Link
            to={`/posts/$postId`}
            params={{ postId: String(post.id) }}
            className="underline font-bold text-lg"
          >
            {post.id}- {post.title}
          </Link>
        </div>
      ))}
      <br />
      <Link
        from={Route.fullPath}
        to="."
        search={(prev) => ({ page: (prev.page || 1) + 1 })}
      >
        Go to Next Page
      </Link>
    </div>
  );
}

